INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM201012C', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{9x^2 + 30x + 25}{3x^2 + 14x + 15}$ is rewritten in the form $\\frac{ax + b}{x + c}$, where $a$, $b$, and $c$ are constants, what is the value of $a + b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$8$"},{"key":"C","text":"$13$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the numerator: $9x^2 + 30x + 25 = (3x + 5)^2$. Factor the denominator: $3x^2 + 14x + 15 = (3x + 5)(x + 3)$. Canceling $(3x + 5)$ gives $\\frac{3x + 5}{x + 3}$, so $a = 3$, $b = 5$, $c = 3$, and $a + b + c = 11$. The distractor $8$ results from incorrectly identifying $c$ as $0$ or miscomputing one of the coefficients. The distractor $13$ comes from an arithmetic error in factoring the denominator as $(3x + 3)(x + 5)$, yielding $c = 5$. The distractor $6$ results from failing to recognize the perfect square trinomial and simplifying incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM207LXCD', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to \\(\\frac{9x^2 - 16}{3x + 4}\\) for all values of \\(x\\) where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"\\(3x - 4\\)"},{"key":"B","text":"\\(3x + 4\\)"},{"key":"C","text":"\\(9x - 4\\)"},{"key":"D","text":"\\(3x^2 - 4\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The numerator \\(9x^2 - 16\\) is a difference of squares: \\((3x)^2 - 4^2 = (3x + 4)(3x - 4)\\). Dividing by \\((3x + 4)\\) yields \\(3x - 4\\). The distractor \\(3x + 4\\) uses the wrong sign from the factoring. The distractor \\(9x - 4\\) incorrectly factors by failing to take the square root of \\(9x^2\\). The distractor \\(3x^2 - 4\\) fails to recognize the difference of squares pattern and attempts to divide each term separately.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM210TOZ0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $11, 14, 17, 17, 19, 23, 27$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$17$"},{"key":"C","text":"$18$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'The data set has $7$ values already in order. The median is the $4$th value, which is $17$. The value $18$ comes from incorrectly averaging the $3$rd and $5$th values ($17$ and $19$). The value $14$ results from selecting the $2$nd value instead of the middle value. The value $19$ results from choosing the $5$th value, miscounting which position is the middle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM218T8RI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function \\(g\\) is defined by \\(g(x) = a \\cdot b^x\\), where \\(a\\) and \\(b\\) are positive constants. If \\(g(2) = 48\\) and \\(g(5) = 6\\), what is the value of \\(g(0)\\)?', NULL, $lyceon_json$[{"key":"A","text":"192"},{"key":"B","text":"384"},{"key":"C","text":"96"},{"key":"D","text":"768"}]$lyceon_json$::jsonb, 'A', NULL, E'Since \\(g(x) = a \\cdot b^x\\), dividing \\(g(5)\\) by \\(g(2)\\) gives \\(\\frac{a \\cdot b^5}{a \\cdot b^2} = b^3 = \\frac{6}{48} = \\frac{1}{8}\\), so \\(b = \\frac{1}{2}\\). Substituting into \\(g(2) = a \\cdot \\left(\\frac{1}{2}\\right)^2 = \\frac{a}{4} = 48\\) gives \\(a = 192\\). Since \\(g(0) = a \\cdot b^0 = a\\), the answer is 192. The value 384 results from computing \\(a = 48 \\cdot 8\\) instead of \\(48 \\cdot 4\\), an arithmetic slip in evaluating \\(b^2\\). The value 96 comes from computing \\(48 \\cdot 2\\) instead of \\(48 \\cdot 4\\), using \\(b\\) instead of \\(b^2\\). The value 768 results from incorrectly setting up \\(a = 48 \\cdot b^5 / b^2\\) as \\(48 \\cdot 16\\) instead of \\(48 \\cdot 4\\).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21SNXCV', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = 4x^2 - 9$. What is the value of $g(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$27$"},{"key":"B","text":"$36$"},{"key":"C","text":"$3$"},{"key":"D","text":"$-9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 3$: $g(3) = 4(3)^2 - 9 = 4(9) - 9 = 36 - 9 = 27$. The distractor $36$ results from computing $4(9)$ but forgetting to subtract $9$. The distractor $3$ comes from an arithmetic error such as computing $4(3) - 9 = 3$. The distractor $-9$ results from substituting $x = 0$ instead of $x = 3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21Y2WFD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees found that 78 drink coffee, 53 drink tea, and 19 drink both coffee and tea. If an employee is chosen at random, what is the probability that the employee drinks coffee or tea?', NULL, $lyceon_json$[{"key":"A","text":"\\dfrac{131}{200}"},{"key":"B","text":"\\dfrac{14}{25}"},{"key":"C","text":"\\dfrac{19}{200}"},{"key":"D","text":"\\dfrac{3}{4}"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the inclusion-exclusion principle, the number who drink coffee or tea is 78 + 53 - 19 = 112. The probability is 112/200, which simplifies to 14/25. The value 131/200 results from adding 78 + 53 without subtracting the 19 who drink both. The value 19/200 represents only those who drink both, not those who drink either. The value 3/4 (150/200) comes from an incorrect setup that overestimates the union.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2320KQC', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(-3, 11)$ and $(5, -13)$. Which of the following is the equation of this line in standard form?', NULL, $lyceon_json$[{"key":"A","text":"$3x + y = 2$"},{"key":"B","text":"$3x + y = -2$"},{"key":"C","text":"$3x - y = 2$"},{"key":"D","text":"$x + 3y = 2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{-13 - 11}{5 - (-3)} = \\frac{-24}{8} = -3$. Using point-slope form with $(-3, 11)$: $y - 11 = -3(x + 3)$, giving $y = -3x - 9 + 11 = -3x + 2$. Rearranging to standard form: $3x + y = 2$. The equation $3x + y = -2$ results from a sign error when computing the constant term. The equation $3x - y = 2$ introduces a second sign error on the $y$ term. The equation $x + 3y = 2$ comes from inverting the slope to $-\\frac{1}{3}$ and rearranging incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25GSX9K', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ that satisfies $\\frac{3(x - 2)}{4} = \\frac{x + 7}{2}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20', ARRAY['20'], E'Multiply both sides by 4 to clear denominators: $3(x - 2) = 2(x + 7)$. Distribute on each side: $3x - 6 = 2x + 14$. Subtract $2x$ from both sides: $x - 6 = 14$. Add 6 to both sides: $x = 20$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25MNQL3', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $5x - 2y = 14$. Line $q$ is perpendicular to line $p$ and passes through the point $(7, -1)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{5}$"},{"key":"B","text":"$\\frac{19}{5}$"},{"key":"C","text":"$-\\frac{9}{5}$"},{"key":"D","text":"$\\frac{5}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting line $p$ in slope-intercept form: $y = \\frac{5}{2}x - 7$, so line $p$ has slope $\\frac{5}{2}$. A perpendicular line has slope $-\\frac{2}{5}$. Using point-slope form with $(7, -1)$: $y + 1 = -\\frac{2}{5}(x - 7)$, which gives $y = -\\frac{2}{5}x + \\frac{14}{5} - 1 = -\\frac{2}{5}x + \\frac{14}{5} - \\frac{5}{5} = -\\frac{2}{5}x + \\frac{9}{5}$. The $y$-intercept is $\\frac{9}{5}$. The value $\\frac{19}{5}$ results from adding 1 instead of subtracting when simplifying. The value $-\\frac{9}{5}$ comes from a sign error on the constant term. The value $\\frac{5}{2}$ confuses the slope of line $p$ with the $y$-intercept of line $q$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25VB61N', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A theater sells adult tickets for 13 dollars each and student tickets for 7 dollars each. The theater must earn more than 910 dollars from ticket sales, and the total number of tickets sold cannot exceed 100. If \\(a\\) represents the number of adult tickets and \\(s\\) represents the number of student tickets, which system of inequalities models this situation?', NULL, $lyceon_json$[{"key":"A","text":"\\(13a + 7s > 910\\) and \\(a + s \\leq 100\\)"},{"key":"B","text":"\\(13a + 7s \\geq 910\\) and \\(a + s < 100\\)"},{"key":"C","text":"\\(7a + 13s > 910\\) and \\(a + s \\leq 100\\)"},{"key":"D","text":"\\(13a + 7s > 910\\) and \\(a + s \\geq 100\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Revenue is \\(13a + 7s\\) and must be strictly more than 910, giving \\(13a + 7s > 910\\). The total tickets cannot exceed 100, giving \\(a + s \\leq 100\\). Using \\(\\geq 910\\) with \\(< 100\\) changes both boundary conditions: it allows exactly 910 in revenue while excluding exactly 100 tickets, neither of which matches the problem. Swapping coefficients to \\(7a + 13s\\) assigns the student price to adults and vice versa. Writing \\(a + s \\geq 100\\) requires at least 100 tickets rather than capping at 100, which reverses the constraint.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25ZY5I7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A linear model for a data set of $14$ points is given by $y = 1.8x + 5.3$. One data point in the set is $(11, 29.7)$. What is the residual for this data point?', NULL, $lyceon_json$[{"key":"A","text":"$-4.6$"},{"key":"B","text":"$4.6$"},{"key":"C","text":"$25.1$"},{"key":"D","text":"$54.8$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted value at $x = 11$ is $1.8(11) + 5.3 = 19.8 + 5.3 = 25.1$. The residual is the actual value minus the predicted value: $29.7 - 25.1 = 4.6$. The value $-4.6$ results from computing predicted minus actual, reversing the residual formula. The value $25.1$ is the predicted value alone, not the residual. The value $54.8$ results from adding the actual and predicted values instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26OVKV2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands at a point on level ground \\(83\\) meters from the base of a vertical tower. The angle of elevation to the top of the tower is \\(29°\\). The surveyor then walks directly toward the tower and stops at a point where the angle of elevation is \\(53°\\). To the nearest tenth of a meter, how far did the surveyor walk?', NULL, $lyceon_json$[{"key":"A","text":"\\(83 - \\dfrac{83\\tan(29°)}{\\tan(53°)}\\)"},{"key":"B","text":"\\(83\\tan(29°) - 83\\tan(53°)\\)"},{"key":"C","text":"\\(83 - \\dfrac{83\\sin(29°)}{\\sin(53°)}\\)"},{"key":"D","text":"\\(\\dfrac{83}{\\tan(53°)} - \\dfrac{83}{\\tan(29°)}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Let \\(h\\) be the height of the tower. From the first position, \\(\\tan(29°) = h/83\\), so \\(h = 83\\tan(29°)\\). From the second position at distance \\(d_2\\) from the base, \\(\\tan(53°) = h/d_2\\), so \\(d_2 = h/\\tan(53°) = 83\\tan(29°)/\\tan(53°)\\). The distance walked is \\(83 - d_2 = 83 - 83\\tan(29°)/\\tan(53°)\\). The expression \\(83\\tan(29°) - 83\\tan(53°)\\) confuses height expressions with distance, an equation setup error. The expression using sine ratios instead of tangent reflects a concept gap about which trigonometric ratio applies. The expression \\(83/\\tan(53°) - 83/\\tan(29°)\\) reverses the subtraction order, yielding a negative value, a sign error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26VM3J8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one of the acute angles measures \\(27°\\). What is the measure, in degrees, of the other acute angle?', NULL, $lyceon_json$[{"key":"A","text":"\\(153°\\)"},{"key":"B","text":"\\(63°\\)"},{"key":"C","text":"\\(27°\\)"},{"key":"D","text":"\\(73°\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'In a right triangle, one angle is \\(90°\\) and the sum of all angles is \\(180°\\). The other acute angle is \\(180° - 90° - 27° = 63°\\). The value \\(153°\\) results from subtracting \\(27°\\) from \\(180°\\) while forgetting the right angle. The value \\(27°\\) assumes both acute angles are equal, a misread of the question. The value \\(73°\\) comes from subtracting \\(27\\) from \\(100\\) instead of from \\(90\\).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28HS33E', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A shipping company charges a flat fee of 11 dollars plus 3 dollars per pound for a package. A customer has at most 47 dollars to spend on shipping. Which inequality represents all possible weights \\(w\\), in pounds, the customer can ship?', NULL, $lyceon_json$[{"key":"A","text":"\\(3w + 11 \\leq 47\\)"},{"key":"B","text":"\\(3w + 11 \\geq 47\\)"},{"key":"C","text":"\\(11w + 3 \\leq 47\\)"},{"key":"D","text":"\\(3w - 11 \\leq 47\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is \\(3w + 11\\), and the customer can spend at most 47 dollars, so the inequality is \\(3w + 11 \\leq 47\\). Using \\(\\geq\\) reverses the budget constraint, meaning the customer must spend at least 47 dollars, which contradicts the problem. Swapping the coefficients to \\(11w + 3\\) misassigns the per-pound rate and the flat fee. Subtracting 11 instead of adding it misrepresents the flat fee as a discount rather than an additional charge.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28J34KE', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A delivery service charges a flat fee plus a per-mile rate. For a 6-mile delivery the total charge is 17 dollars, and for a 14-mile delivery the total charge is 29 dollars. What is the flat fee, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$7$"},{"key":"C","text":"$1.50$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $f$ be the flat fee and $r$ the per-mile rate. Then $f + 6r = 17$ and $f + 14r = 29$. Subtracting the first equation from the second: $8r = 12$, so $r = 1.50$. Substituting back: $f + 6(1.50) = 17$, giving $f + 9 = 17$, so $f = 8$. The value 7 results from an arithmetic slip when subtracting 9 from 17. The value 1.50 is the per-mile rate, not the flat fee. The value 11 comes from subtracting only $6$ instead of $9$ from 17.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28UJFSX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'The population of a town increased from $8{,}300$ to $9{,}047$. What is the percent increase in the town''s population?', NULL, $lyceon_json$[{"key":"A","text":"$7\\%$"},{"key":"B","text":"$8.3\\%$"},{"key":"C","text":"$9\\%$"},{"key":"D","text":"$10.9\\%$"}]$lyceon_json$::jsonb, 'C', NULL, E'The increase is $9{,}047 - 8{,}300 = 747$. The percent increase is $\\frac{747}{8{,}300} \\times 100 = 9\\%$. The value $8.3\\%$ results from dividing $747$ by $9{,}047$ (using the new population as the base instead of the original). The value $7\\%$ comes from a computational error in the division. The value $10.9\\%$ arises from miscomputing the difference or using an incorrect denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM290NW5G', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation $2x^2 - 11x + 17 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"Infinitely many"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = (-11)^2 - 4(2)(17) = 121 - 136 = -15$. Since the discriminant is negative, the equation has $0$ real solutions. The distractor $1$ reflects confusing a negative discriminant with a zero discriminant (which yields exactly one repeated root). The distractor $2$ assumes every quadratic has two real solutions. The distractor stating infinitely many solutions does not apply to a quadratic equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29JJ9M7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A class has 31 students. Of these, 13 are in the debate club, 11 are in the science club, and 5 are in both clubs. If a student who is in the debate club is selected at random, what is the probability that this student is NOT in the science club?', NULL, $lyceon_json$[{"key":"A","text":"\\dfrac{8}{13}"},{"key":"B","text":"\\dfrac{5}{13}"},{"key":"C","text":"\\dfrac{8}{31}"},{"key":"D","text":"\\dfrac{18}{31}"}]$lyceon_json$::jsonb, 'A', NULL, E'Given that the student is in the debate club, the sample space is the 13 debate club members. Of these 13, exactly 5 are also in the science club, so 13 - 5 = 8 are in the debate club only. The conditional probability is 8/13. The value 5/13 results from finding the probability of being in the science club given debate club membership rather than not being in it. The value 8/31 incorrectly uses the total class size as the denominator instead of conditioning on debate club membership. The value 18/31 uses the total class size and miscounts students not in the science club.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A39HX3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A researcher surveys a random sample of 600 high school students and finds that 37% participate in after-school athletics. The margin of error for this estimate is 4 percentage points at a 95% confidence level. A second researcher surveys a random sample of 150 students from the same population. If the second sample yields the same proportion, how will the margin of error for the second sample compare to that of the first?', NULL, $lyceon_json$[{"key":"A","text":"It will be approximately the same because the sample proportion is the same."},{"key":"B","text":"It will be smaller because smaller samples produce more precise estimates."},{"key":"C","text":"It will be approximately 8 percentage points because the margin of error is inversely proportional to the sample size."},{"key":"D","text":"It will be approximately 8 percentage points because the margin of error is inversely proportional to the square root of the sample size."}]$lyceon_json$::jsonb, 'D', NULL, E'The margin of error is inversely proportional to the square root of the sample size. With the sample size reduced from 600 to 150, the ratio of sample sizes is 600/150 = 4, so the square root of this ratio is 2. The margin of error for the second sample is approximately 4 times 2 = 8 percentage points. Claiming the margin stays the same ignores the effect of sample size on precision. Saying smaller samples are more precise reverses the actual relationship. Stating the margin of error is inversely proportional to the sample size (rather than its square root) applies the wrong relationship and would yield 16 percentage points.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A4SCXR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone and a cylinder share the same circular base with radius \\(r\\) and the same height \\(h\\). The volume of the cylinder is \\(531\\pi\\) cubic units. What is the volume, in cubic units, of the cone?', NULL, $lyceon_json$[{"key":"A","text":"\\(177\\pi\\)"},{"key":"B","text":"\\(265.5\\pi\\)"},{"key":"C","text":"\\(1593\\pi\\)"},{"key":"D","text":"\\(354\\pi\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of a cylinder is \\(V_{\\text{cyl}} = \\pi r^2 h\\) and the volume of a cone with the same base and height is \\(V_{\\text{cone}} = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3} V_{\\text{cyl}}\\). Therefore \\(V_{\\text{cone}} = \\frac{531\\pi}{3} = 177\\pi\\). The value \\(265.5\\pi\\) divides by \\(2\\) instead of \\(3\\), reflecting a concept gap about the cone-to-cylinder volume relationship. The value \\(1593\\pi\\) multiplies by \\(3\\) instead of dividing, an equation setup error reversing the relationship. The value \\(354\\pi\\) computes \\(531 \\times \\frac{2}{3}\\) instead of \\(531 \\times \\frac{1}{3}\\), an arithmetic slip.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B60S2T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A bakery produces \\(84\\) loaves of bread every \\(6\\) hours. At this constant rate, how many loaves does the bakery produce in \\(5\\) hours?', NULL, $lyceon_json$[{"key":"A","text":"70"},{"key":"B","text":"14"},{"key":"C","text":"60"},{"key":"D","text":"30"}]$lyceon_json$::jsonb, 'A', NULL, E'The unit rate is \\(\\frac{84}{6} = 14\\) loaves per hour. In 5 hours the bakery produces \\(14 \\times 5 = 70\\) loaves. The value 14 results from finding the unit rate but not multiplying by the number of hours. The value 60 comes from an arithmetic error in the multiplication step. The value 30 results from incorrectly computing \\(6 \\times 5\\) rather than using the unit rate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CGJFHN', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = -4x + 23$. What is the value of $g(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$35$"},{"key":"B","text":"$11$"},{"key":"C","text":"$-11$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 3$: $g(3) = -4(3) + 23 = -12 + 23 = 11$. The value 35 comes from incorrectly treating the coefficient as positive, computing $12 + 23$. The value $-11$ results from subtracting 23 instead of adding it, computing $-12 - 23$ and mishandling the magnitude. The value 19 results from failing to multiply by 3, computing $-4 + 23$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CYOFRJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h$ is defined by $h(x) = -(x - 4)^2 + 11$. What is the maximum value of $h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$11$"},{"key":"B","text":"$4$"},{"key":"C","text":"$-11$"},{"key":"D","text":"$27$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $h(x) = -(x - 4)^2 + 11$ is a downward-opening parabola in vertex form $a(x - h)^2 + k$ with vertex at $(4, 11)$. Since $a = -1 < 0$, the parabola opens downward and the vertex represents the maximum. Therefore the maximum value is $11$. The distractor $4$ confuses the $x$-coordinate of the vertex with the maximum value. The distractor $-11$ applies an incorrect sign to the $k$ value. The distractor $27$ results from incorrectly expanding and evaluating the function.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DAA65M', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle \\(JKL\\), the exterior angle at vertex \\(L\\) measures \\((7x + 3)°\\). The two non-adjacent interior angles measure \\((4x - 9)°\\) at vertex \\(J\\) and \\((2x + 26)°\\) at vertex \\(K\\). What is the measure, in degrees, of the interior angle at vertex \\(L\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(101°\\)"},{"key":"B","text":"\\(79°\\)"},{"key":"C","text":"\\(14°\\)"},{"key":"D","text":"\\(47°\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'By the exterior angle theorem, the exterior angle equals the sum of the two non-adjacent interior angles: \\(7x + 3 = (4x - 9) + (2x + 26)\\), which gives \\(7x + 3 = 6x + 17\\), so \\(x = 14\\). The exterior angle at \\(L\\) is \\(7(14) + 3 = 101°\\), so the interior angle at \\(L\\) is \\(180° - 101° = 79°\\). The value \\(101°\\) is the exterior angle itself, not the interior angle, representing partial reasoning where the student stops too early. The value \\(14°\\) reports the value of \\(x\\) rather than the angle, also partial reasoning. The value \\(47°\\) results from substituting \\(x = 14\\) into \\(4x - 9 = 47°\\) and reporting angle \\(J\\) instead of angle \\(L\\), an equation setup error in identifying which angle was asked for.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DRZ54I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A poll of 400 randomly selected residents found that 54% preferred candidate X, with a margin of error of 3.5 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly 54% of all residents prefer candidate X."},{"key":"B","text":"Between 50.5% and 57.5% of all residents are plausibly estimated to prefer candidate X."},{"key":"C","text":"If the poll were repeated, exactly 54% of respondents would prefer candidate X every time."},{"key":"D","text":"At most 57.5% of all residents prefer candidate X."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of 3.5 percentage points means the plausible range for the true population proportion is 54% plus or minus 3.5%, which gives the interval from 50.5% to 57.5%. Stating that exactly 54% of all residents prefer candidate X treats the sample statistic as the exact population parameter, ignoring sampling variability. Claiming the result would be exactly 54% every time misunderstands that sample results vary across different samples. Saying at most 57.5% captures only the upper bound and omits the lower bound of the interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EY1IV0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A class of $23$ students has a mean test score of $74$. The teacher removes the two lowest scores, $41$ and $53$, to calculate an adjusted mean. What is the adjusted mean of the remaining $21$ scores, rounded to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"$76.6$"},{"key":"B","text":"$78.2$"},{"key":"C","text":"$80.4$"},{"key":"D","text":"$74.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total of all $23$ scores is $23 \\times 74 = 1{,}702$. Removing the two scores gives $1{,}702 - 41 - 53 = 1{,}608$. The adjusted mean is $\\frac{1{,}608}{21} \\approx 76.6$. The value $74.5$ results from dividing the removed total by the wrong count or making only a small adjustment. The value $78.2$ comes from an arithmetic error in the subtraction or division. The value $80.4$ results from dividing $1{,}608$ by $20$ instead of $21$, miscounting the remaining students.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FFI4IZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $x > 0$ and $y > 0$ satisfy the system $$x^2 + y = 19$$ $$x + y = 13,$$ what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'From the second equation, $y = 13 - x$. Substituting into the first equation: $x^2 + (13 - x) = 19$, which simplifies to $x^2 - x - 6 = 0$. Factoring gives $(x - 3)(x + 2) = 0$, so $x = 3$ or $x = -2$. Since $x > 0$, the answer is $x = 3$. (Checking: $y = 13 - 3 = 10 > 0$, and $9 + 10 = 19$.)', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FWWM2S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers randomly assign 120 participants to two groups. One group receives a new herbal supplement daily for 8 weeks, while the other group receives an identical-looking placebo. Neither the participants nor the researchers measuring outcomes know which group each participant is in. At the end of the study, the supplement group shows significantly lower stress levels. Which feature of the study design allows the researchers to conclude that the supplement likely caused the reduction in stress?', NULL, $lyceon_json$[{"key":"A","text":"The use of a placebo that looks identical to the supplement"},{"key":"B","text":"The random assignment of participants to the two groups"},{"key":"C","text":"The fact that neither participants nor researchers knew the group assignments"},{"key":"D","text":"The 8-week duration of the study"}]$lyceon_json$::jsonb, 'B', NULL, E'Random assignment is the key feature that allows a causal conclusion, because it ensures that confounding variables are approximately equally distributed across the treatment and control groups. The identical placebo controls for the placebo effect but does not itself establish causation. Double-blinding (neither participants nor researchers knowing assignments) reduces bias in measurement and behavior but is not the feature that establishes causal inference. The 8-week duration affects the study''s ability to detect effects but does not enable causal conclusions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HFL93P', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'For what value of $k$ does the equation $k(x + 3) - 2x = 5x + 9$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$3$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Expanding the left side gives $kx + 3k - 2x = 5x + 9$, which simplifies to $(k - 2)x + 3k = 5x + 9$. Collecting $x$ terms: $(k - 7)x = 9 - 3k$. For no solution, the coefficient of $x$ must be zero while the constant is nonzero. Setting $k - 7 = 0$ gives $k = 7$. Checking: $9 - 3(7) = -12 \\neq 0$, confirming no solution exists. The value $-7$ results from a sign error when setting $k - 7 = 0$. The value 3 comes from incorrectly solving $3k = 9$ instead of finding when the $x$-coefficient vanishes. The value 9 comes from misidentifying the constant on the right side as the answer.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HWGLX8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation \\((x - 7)^2 + (y + 11)^2 = 49\\) defines a circle in the \\(xy\\)-plane. Which of the following is the length of the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"\\(7\\)"},{"key":"B","text":"\\(49\\)"},{"key":"C","text":"\\(14\\)"},{"key":"D","text":"\\(\\sqrt{7}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The standard form of a circle is \\((x - h)^2 + (y - k)^2 = r^2\\). Here \\(r^2 = 49\\), so \\(r = 7\\). The value \\(49\\) mistakes \\(r^2\\) for \\(r\\), a concept gap about the standard form. The value \\(14\\) doubles the radius, confusing radius with diameter, an equation setup error. The value \\(\\sqrt{7}\\) takes the square root of \\(7\\) rather than of \\(49\\), reflecting partial reasoning where the student takes a square root of the wrong quantity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IC9H1V', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A school counselor reviews student records and finds that students who participate in at least one extracurricular activity have higher grade point averages than students who do not participate in any. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Participating in extracurricular activities causes higher grades."},{"key":"B","text":"There is an association between participation in extracurricular activities and higher grade point averages."},{"key":"C","text":"Students should be required to join an extracurricular activity to improve their grades."},{"key":"D","text":"Students with higher grades have more free time for extracurricular activities."}]$lyceon_json$::jsonb, 'B', NULL, E'Because this is an observational study based on reviewing existing records without random assignment, only an association can be established, not causation. Claiming that participation causes higher grades asserts causation, which requires a randomized controlled experiment. Recommending that students be required to join activities goes beyond what the data supports and introduces a policy judgment. Stating that students with higher grades have more free time reverses the direction and asserts a causal claim without evidence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JFENSM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains 7 red marbles, 4 blue marbles, and 3 green marbles. If one marble is selected at random, what is the probability that the marble is blue?', NULL, $lyceon_json$[{"key":"A","text":"\\dfrac{1}{7}"},{"key":"B","text":"\\dfrac{2}{7}"},{"key":"C","text":"\\dfrac{3}{14}"},{"key":"D","text":"\\dfrac{4}{11}"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of marbles is 7 + 4 + 3 = 14. The probability of selecting a blue marble is 4/14, which simplifies to 2/7. The value 1/7 results from incorrectly simplifying 4/14 as if it were 2/14. The value 3/14 comes from using the count of green marbles instead of blue marbles. The value 4/11 results from dividing the blue count by only the non-blue marbles (7 + 3 = 10, misread as 11) instead of the total.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JH1JMP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the angles formed measures \\(3x + 14\\) degrees and its alternate interior angle measures \\(5x - 22\\) degrees. What is the measure, in degrees, of each of these angles?', NULL, $lyceon_json$[{"key":"A","text":"\\(68°\\)"},{"key":"B","text":"\\(18°\\)"},{"key":"C","text":"\\(72°\\)"},{"key":"D","text":"\\(112°\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Alternate interior angles formed by parallel lines and a transversal are equal, so \\(3x + 14 = 5x - 22\\). Solving: \\(14 + 22 = 5x - 3x\\), so \\(36 = 2x\\) and \\(x = 18\\). Substituting back: \\(3(18) + 14 = 68°\\). The value \\(18°\\) is the value of \\(x\\) alone, not the angle measure, representing partial reasoning. The value \\(72°\\) arises from setting the angles as supplementary (\\(3x + 14 + 5x - 22 = 180\\)) instead of equal, an equation setup error. The value \\(112°\\) comes from computing \\(180 - 68\\), treating the angles as supplementary after finding the correct value, reflecting a concept gap.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KKQSIJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'The mean of $9$ values is $37$. If a tenth value of $53$ is added to the data set, what is the mean of all $10$ values?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '38.6', ARRAY['193/5', '38.6'], E'The sum of the original $9$ values is $9 \\times 37 = 333$. Adding $53$ gives a new sum of $333 + 53 = 386$. The new mean is $\\frac{386}{10} = 38.6$. A common error is averaging $37$ and $53$ to get $45$, which would be correct only if the two groups had equal size. Another error is dividing $386$ by $9$ instead of $10$, yielding approximately $42.9$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L46MGF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle \\(DEF\\), the measure of angle \\(D\\) is \\(53°\\) and the measure of angle \\(E\\) is \\(71°\\). What is the measure, in degrees, of angle \\(F\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(56°\\)"},{"key":"B","text":"\\(46°\\)"},{"key":"C","text":"\\(66°\\)"},{"key":"D","text":"\\(124°\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of the interior angles of a triangle is \\(180°\\). Therefore, angle \\(F = 180° - 53° - 71° = 56°\\). The value \\(46°\\) results from computing \\(180 - 63 - 71\\), an arithmetic slip in reading one angle. The value \\(66°\\) results from computing \\(180 - 53 - 71\\) incorrectly as \\(66\\). The value \\(124°\\) comes from adding \\(53 + 71 = 124\\) and reporting it as the angle rather than subtracting from \\(180°\\), reflecting a concept gap about angle sums.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L4WJ50', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A cyclist rides at a constant speed of $17$ kilometers per hour. Given that $1$ kilometer $\\approx 0.6214$ miles, which of the following is closest to the cyclist''s speed, in miles per hour?', NULL, $lyceon_json$[{"key":"A","text":"$9.4$"},{"key":"B","text":"$10.6$"},{"key":"C","text":"$27.4$"},{"key":"D","text":"$11.2$"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiplying $17 \\times 0.6214 \\approx 10.56$, which is closest to $10.6$. The value $27.4$ results from dividing $17$ by $0.6214$ instead of multiplying, which inverts the conversion direction. The value $9.4$ comes from a multiplication error such as using $0.55$ instead of $0.6214$. The value $11.2$ arises from rounding $0.6214$ up to $0.66$ before multiplying.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L6H6GX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $45$ dollars is marked down by $20\\%$. What is the sale price, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$25$"},{"key":"C","text":"$36$"},{"key":"D","text":"$40.50$"}]$lyceon_json$::jsonb, 'C', NULL, E'A $20\\%$ discount on $45$ dollars is $0.20 \\times 45 = 9$ dollars. The sale price is $45 - 9 = 36$ dollars. The value $9$ is only the discount amount, not the sale price. The value $25$ results from subtracting $20$ from $45$ instead of computing $20\\%$ of $45$. The value $40.50$ comes from subtracting $10\\%$ instead of $20\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LQU1RW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher wants to determine whether a new study technique improves exam scores. She recruits 90 volunteers and lets each choose whether to use the new technique or their usual method. Students who choose the new technique score an average of 7 points higher. A campus newspaper reports that the new technique boosts exam scores by 7 points. Which of the following best explains why the newspaper''s claim may not be valid?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of 90 is too small to detect a 7-point difference."},{"key":"B","text":"Students who chose the new technique may differ systematically from those who did not, making it impossible to attribute the difference solely to the technique."},{"key":"C","text":"The study did not use a placebo, so the results are unreliable."},{"key":"D","text":"The 7-point difference is not statistically significant because no confidence interval was reported."}]$lyceon_json$::jsonb, 'B', NULL, E'Because participants self-selected into groups rather than being randomly assigned, there may be confounding variables. Students who chose the new technique may be more motivated, better organized, or otherwise systematically different from those who did not. This self-selection bias means the 7-point difference cannot be attributed solely to the technique. A sample of 90 is not inherently too small to detect such a difference. The absence of a placebo is a concern in some experiments but is not the fundamental flaw here; the lack of random assignment is. Whether a confidence interval was reported is a reporting concern, not the core design flaw that undermines the causal claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M7T8ZS', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'For what value of \\(k\\) does the system of equations \\(2x + 3y = 7\\) and \\(kx + 9y = 14\\) have no solution?', NULL, $lyceon_json$[{"key":"A","text":"\\(3\\)"},{"key":"B","text":"\\(6\\)"},{"key":"C","text":"\\(-6\\)"},{"key":"D","text":"\\(2\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'For no solution, the lines must be parallel: same slope but different intercepts. The first equation has slope \\(-\\frac{2}{3}\\). The second has slope \\(-\\frac{k}{9}\\). Setting slopes equal: \\(-\\frac{2}{3} = -\\frac{k}{9}\\), so \\(k = 6\\). Checking intercepts: the first equation gives \\(y\\)-intercept \\(\\frac{7}{3}\\), and with \\(k = 6\\) the second gives \\(y\\)-intercept \\(\\frac{14}{9}\\). Since \\(\\frac{7}{3} \\neq \\frac{14}{9}\\), the lines are parallel and distinct, confirming no solution. The value 3 results from dividing 9 by 3 instead of cross-multiplying. The value \\(-6\\) introduces a sign error in the cross-multiplication. The value 2 confuses the coefficient of \\(x\\) in the first equation with the answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MYTGWE', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the \\(y\\)-intercept of the line \\(7x - 3y = 21\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\((0, 7)\\)"},{"key":"B","text":"\\((0, -7)\\)"},{"key":"C","text":"\\((0, 3)\\)"},{"key":"D","text":"\\((0, -3)\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting \\(x = 0\\) in \\(7x - 3y = 21\\) gives \\(-3y = 21\\), so \\(y = -7\\). The \\(y\\)-intercept is \\((0, -7)\\). The point \\((0, 7)\\) results from dropping the negative sign when dividing by \\(-3\\). The point \\((0, 3)\\) comes from dividing 21 by 7 instead of by \\(-3\\), confusing the coefficient of \\(x\\) with that of \\(y\\). The point \\((0, -3)\\) results from using the coefficient of \\(y\\) as the intercept value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N04QH2', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3(2x - 7) + 5x$?', NULL, $lyceon_json$[{"key":"A","text":"$11x - 21$"},{"key":"B","text":"$11x - 7$"},{"key":"C","text":"$6x - 21$"},{"key":"D","text":"$11x + 21$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $3 \\cdot 2x - 3 \\cdot 7 + 5x = 6x - 21 + 5x = 11x - 21$. The distractor $11x - 7$ results from failing to distribute the $3$ to the $-7$ term. The distractor $6x - 21$ omits the $+5x$ term entirely. The distractor $11x + 21$ incorrectly treats $-3 \\cdot 7$ as positive $21$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NV5TJB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up an item by $40\\%$ over its cost and then offers a $25\\%$ discount on the marked-up price. If the sale price is $63$ dollars, what was the store''s cost for the item, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$45$"},{"key":"B","text":"$60$"},{"key":"C","text":"$47.25$"},{"key":"D","text":"$84$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $c$ be the cost. The marked-up price is $1.40c$, and after a $25\\%$ discount the sale price is $0.75 \\times 1.40c = 1.05c$. Setting $1.05c = 63$ gives $c = 60$ dollars. The value $45$ results from dividing $63$ only by $1.40$, ignoring the discount step. The value $84$ results from dividing $63$ only by $0.75$, ignoring the markup step. The value $47.25$ results from multiplying $63$ by $0.75$ (applying the discount forward) instead of dividing to reverse it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OJDD51', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'grid_in', E'A line of best fit for a data set is modeled by $y = 2.3x + 11$. According to this model, what is the predicted value of $y$ when $x = 7$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '27.1', ARRAY['27.1'], E'Substituting $x = 7$ into the equation gives $y = 2.3(7) + 11 = 16.1 + 11 = 27.1$. A common error is forgetting to add the $y$-intercept, yielding $16.1$. Another error is multiplying $2.3 \\times 11$ instead of using $x = 7$, which gives an unrelated value.', NULL, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P6RZAS', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of \\(x\\) satisfies the equation \\(8x - 23 = 41\\)?', NULL, $lyceon_json$[{"key":"A","text":"8"},{"key":"B","text":"\\(\\dfrac{18}{8}\\)"},{"key":"C","text":"64"},{"key":"D","text":"-8"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding 23 to both sides gives \\(8x = 64\\), and dividing both sides by 8 gives \\(x = 8\\). The value \\(\\frac{18}{8}\\) results from subtracting 23 from 41 to get 18 and then dividing by 8, missing the addition step. The value 64 reflects stopping at \\(8x = 64\\) and misreading that intermediate result as the answer without dividing by 8. The value \\(-8\\) results from a sign error when isolating \\(x\\).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q4WOJM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle \\(DEF\\), angle \\(F\\) is the right angle. If \\(\\sin(D) = \\dfrac{19}{37}\\), what is the value of \\(\\cos(E)\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19/37', ARRAY['19/37', '0.513', '.513', '0.514', '.514'], E'In right triangle \\(DEF\\) with the right angle at \\(F\\), angles \\(D\\) and \\(E\\) are complementary (they sum to \\(90°\\)). A fundamental trigonometric identity states that \\(\\cos(E) = \\sin(90° - E) = \\sin(D)\\). Therefore \\(\\cos(E) = \\dfrac{19}{37}\\). A common error is computing \\(\\cos(E)\\) as \\(\\dfrac{\\text{adjacent}}{\\text{hypotenuse}}\\) from the wrong triangle perspective, or confusing sine and cosine definitions, which would yield an incorrect ratio.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q6GDRB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle in the \\(xy\\)-plane has equation \\(x^2 + y^2 - 6x + 14y + 33 = 0\\). What is the radius of this circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Complete the square for both variables. Group terms: \\((x^2 - 6x) + (y^2 + 14y) = -33\\). Complete the square: \\((x^2 - 6x + 9) + (y^2 + 14y + 49) = -33 + 9 + 49\\), giving \\((x - 3)^2 + (y + 7)^2 = 25\\). Therefore \\(r^2 = 25\\) and \\(r = 5\\). A common error is forgetting to add the completing-the-square constants to both sides, yielding an incorrect value under the radical. Another error is reporting \\(r^2 = 25\\) as the radius instead of taking the square root.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QFW77N', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'In the solution \\((x, y)\\) to the system of equations \\(3x + 11y = 65\\) and \\(5x - 4y = 19\\), what is the value of \\(x + y\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Multiply the first equation by 4 and the second by 11 to align the \\(y\\)-coefficients for elimination: \\(12x + 44y = 260\\) and \\(55x - 44y = 209\\). Adding these gives \\(67x = 469\\), so \\(x = 7\\). Substituting \\(x = 7\\) into the first equation: \\(21 + 11y = 65\\), which gives \\(11y = 44\\), so \\(y = 4\\). Therefore \\(x + y = 7 + 4 = 11\\). Verification with the second equation: \\(5(7) - 4(4) = 35 - 16 = 19\\), which confirms the solution.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R75FMO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A right circular cylinder has a height of \\(11\\) centimeters and a base radius of \\(4\\) centimeters. What is the volume, in cubic centimeters, of the cylinder? (Express your answer in terms of \\(\\pi\\) as a whole number times \\(\\pi\\); enter only the whole number coefficient.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '176', ARRAY['176'], E'The volume of a cylinder is \\(V = \\pi r^2 h\\). Substituting \\(r = 4\\) and \\(h = 11\\): \\(V = \\pi(4)^2(11) = \\pi(16)(11) = 176\\pi\\) cubic centimeters. The whole-number coefficient is \\(176\\). A common error is using the diameter instead of the radius, computing \\(\\pi(8)^2(11) = 704\\pi\\). Another error is using the circumference formula component \\(2\\pi r h\\) (lateral surface area) instead of the volume formula, yielding \\(88\\pi\\).', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S1T64N', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The linear function $h$ satisfies $h(2) = 19$ and $h(9) = -16$. For what value of $x$ does $h(x) = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '29/5', ARRAY['29/5', '5.8'], E'The slope of $h$ is $\\frac{-16 - 19}{9 - 2} = \\frac{-35}{7} = -5$. Using point-slope form with $(2, 19)$: $h(x) = -5(x - 2) + 19 = -5x + 10 + 19 = -5x + 29$. Setting $h(x) = 0$: $-5x + 29 = 0$, so $5x = 29$, giving $x = \\frac{29}{5}$. Verification: $h\\left(\\frac{29}{5}\\right) = -5 \\cdot \\frac{29}{5} + 29 = -29 + 29 = 0$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SQHMHZ', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'What is the value of \\(x\\) in the solution to the system of equations \\(x + y = 19\\) and \\(x - y = 5\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'Adding the two equations eliminates \\(y\\): \\((x + y) + (x - y) = 19 + 5\\), which simplifies to \\(2x = 24\\), so \\(x = 12\\). Substituting back, \\(y = 7\\), and both equations are satisfied: \\(12 + 7 = 19\\) and \\(12 - 7 = 5\\).', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UL7YFI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of \\(23\\) inches and a width of \\(9\\) inches. What is the area, in square inches, of the rectangle?', NULL, $lyceon_json$[{"key":"A","text":"\\(207\\)"},{"key":"B","text":"\\(64\\)"},{"key":"C","text":"\\(32\\)"},{"key":"D","text":"\\(216\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The area of a rectangle is length times width: \\(23 \\times 9 = 207\\) square inches. The value \\(64\\) computes the perimeter \\(2(23 + 9) = 64\\) instead of the area, an equation setup error. The value \\(32\\) computes half the perimeter \\(23 + 9 = 32\\), a concept gap about the area formula. The value \\(216\\) results from computing \\(24 \\times 9\\) instead of \\(23 \\times 9\\), an arithmetic slip.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UPL3ZY', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of \\(x\\) satisfies the inequality \\(7x - 19 > 2\\)?', NULL, $lyceon_json$[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"1"}]$lyceon_json$::jsonb, 'C', NULL, E'Solving \\(7x - 19 > 2\\) gives \\(7x > 21\\), so \\(x > 3\\). Among the choices, only 4 is greater than 3. The value 3 fails because the inequality is strict (not \\(\\geq\\)). The value 2 results from an arithmetic slip when dividing, and 1 is too small by any calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V1D0BR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 250 voters in a city found that 145 support a new park proposal. Based on this sample, what is the best estimate of the percentage of all voters in the city who support the proposal?', NULL, $lyceon_json$[{"key":"A","text":"42\\%"},{"key":"B","text":"52\\%"},{"key":"C","text":"58\\%"},{"key":"D","text":"68\\%"}]$lyceon_json$::jsonb, 'C', NULL, E'The sample proportion is 145/250 = 0.58, or 58%. This is the best point estimate of the population proportion. The value 42% is the complement (100% - 58%), representing those who do not support the proposal. The value 52% comes from an arithmetic error in the division. The value 68% results from an incorrect calculation such as misreading the sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W3QB7W', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution of $x^2 - 49 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The equation $x^2 - 49 = 0$ can be rewritten as $x^2 = 49$. Taking the square root of both sides gives $x = 7$ or $x = -7$. Since the question asks for the positive solution, the answer is $7$.', NULL, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y2RXMS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of \\(38\\) centimeters. What is the circumference, in centimeters, of this circle?', NULL, $lyceon_json$[{"key":"A","text":"\\(19\\pi\\)"},{"key":"B","text":"\\(38\\pi\\)"},{"key":"C","text":"\\(361\\pi\\)"},{"key":"D","text":"\\(76\\pi\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is \\(C = \\pi d\\), where \\(d\\) is the diameter. So \\(C = 38\\pi\\) centimeters. The value \\(19\\pi\\) uses the radius instead of the diameter in the formula \\(C = \\pi d\\), confusing it with \\(C = \\pi r\\), a concept gap. The value \\(361\\pi\\) computes the area formula \\(\\pi r^2 = \\pi(19)^2\\), using the area formula instead of circumference, an equation setup error. The value \\(76\\pi\\) doubles the diameter, computing \\(2 \\times 38 \\times \\pi\\), an arithmetic slip from applying \\(C = 2\\pi d\\) instead of \\(C = \\pi d\\).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YPWICU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A recipe calls for flour, sugar, and butter in a ratio of $7:4:3$ by weight. A baker has $546$ grams of flour and wants to use all of it. She realizes she is $39$ grams short on sugar. How many grams of sugar does the baker currently have?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '273', ARRAY['273'], E'From the ratio, flour corresponds to $7$ parts and sugar to $4$ parts. Since $546$ grams of flour equals $7$ parts, one part is $\\frac{546}{7} = 78$ grams. The sugar needed is $4 \\times 78 = 312$ grams. Because the baker is $39$ grams short, she currently has $312 - 39 = 273$ grams of sugar. A common error is stopping at $312$ grams without subtracting the shortage. Another error is adding $39$ instead of subtracting, yielding $351$. Computing $3 \\times 78 = 234$ uses the butter ratio instead of the sugar ratio.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZCM715', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of hours spent studying ($x$) and the corresponding exam score ($y$) for a group of students. The line of best fit is $y = 1.7x + 58.4$. Which of the following is the best interpretation of the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour spent studying, the predicted exam score increases by $1.7$ points."},{"key":"B","text":"For each additional point on the exam, the predicted study time increases by $1.7$ hours."},{"key":"C","text":"A student who does not study is predicted to score $1.7$ points."},{"key":"D","text":"The exam score and study time have a correlation of $1.7$."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of a linear model represents the predicted change in $y$ for each unit increase in $x$. Here, $1.7$ means that for each additional hour of studying, the predicted exam score increases by $1.7$ points. Interpreting it as $1.7$ hours per additional point reverses the roles of the variables. Stating that a student who does not study scores $1.7$ confuses the slope with the $y$-intercept, which is $58.4$. A correlation coefficient is a value between $-1$ and $1$, so $1.7$ cannot be a correlation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20L5HDL', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Historian Kwame Adjei contends that the treaty of 1897, far from settling territorial disputes in the region, actually ______ them: by redrawing boundaries without consulting local chieftains, colonial administrators introduced overlapping land claims that persisted well into the twentieth century and fueled periodic outbreaks of violence.', $lyceon_json$[{"key":"A","text":"exacerbated"},{"key":"B","text":"adjudicated"},{"key":"C","text":"enumerated"},{"key":"D","text":"rescinded"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts the treaty''s intended purpose of settling disputes with its actual effect: creating overlapping land claims and fueling violence. "Exacerbated" means to make worse, which fits this contrast perfectly — the treaty worsened the disputes rather than resolving them. "Adjudicated" means to formally judge or settle a dispute, which contradicts the passage''s point that the treaty failed to settle anything. "Enumerated" means to list or count, which is incoherent in the context of what the treaty did to territorial disputes. "Rescinded" means to revoke or cancel, but the passage does not say the disputes were canceled — it says they were intensified and prolonged.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20ZOPFD', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if true, would most directly undermine the researchers'' conclusion?', E'A team of neuroscientists at the Karolinska Institute conducted a study in which 83 participants performed a spatial reasoning task after either a 90-minute nap or an equivalent period of quiet wakefulness. The nap group scored 23 percent higher on the task, leading the researchers to conclude that sleep — specifically, the memory consolidation that occurs during slow-wave sleep — was responsible for the performance improvement. The researchers controlled for prior sleep deprivation, caffeine intake, and time of day.', $lyceon_json$[{"key":"A","text":"Electroencephalogram data showed that 61 of the 83 participants in the nap group did not enter slow-wave sleep during the 90-minute nap period."},{"key":"B","text":"Participants who reported higher baseline spatial reasoning ability were equally distributed between the nap and wakefulness groups."},{"key":"C","text":"A follow-up study with 200 participants replicated the 23 percent performance difference between the nap and wakefulness groups."},{"key":"D","text":"The spatial reasoning task used in the study had been validated in three prior peer-reviewed experiments."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers attributed the performance boost specifically to slow-wave sleep consolidation. The finding that most nap-group participants never entered slow-wave sleep directly undermines this causal mechanism — if the improvement occurred without slow-wave sleep, the conclusion about slow-wave consolidation being responsible cannot hold. The finding about equal distribution of baseline ability supports the study''s validity rather than undermining its conclusion. The replication finding strengthens rather than undermines the conclusion. The task validation finding supports the study''s methodology, not challenges its conclusion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21GLXCD', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Yael Berenson studied wage growth in seventeen midsize European cities between 2009 and 2021. In cities where public transit networks expanded significantly during that period, median wages rose by an average of eleven percent. In cities without major transit investment, median wages grew by only four percent. _______ Berenson cautioned that the correlation does not establish causation, since cities that invested in transit may also have pursued other economic development policies that contributed to wage growth.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"However,"},{"key":"C","text":"Therefore,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'B', NULL, E'The data presented before the blank suggests a link between transit expansion and wage growth, but the sentence after the blank introduces a caveat that the correlation may not reflect causation. "However," correctly signals this shift from an apparent finding to a qualification that complicates its interpretation. "Moreover," would add supporting information, but the caution about confounding variables undermines rather than reinforces the implication of the data. "Therefore," would signal that the caution is a logical conclusion of the data, but the caution actually challenges the straightforward reading of the data rather than following from it. "For example," would introduce an illustrative case, but Berenson''s caveat is a methodological qualification, not a specific instance of the trend.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22URCDU', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø have documented an unusual adaptation in Arctic reindeer: their eyes change color with the seasons. During the long, bright Arctic summer, the tapetum lucidum — a reflective layer behind the retina — appears golden. In winter darkness, however, it shifts to a deep blue, which scatters more light within the eye and increases sensitivity to the dim conditions. This seasonal color change, unique among mammals, allows the reindeer to detect predators and forage for lichen even during months of near-total darkness.', $lyceon_json$[{"key":"A","text":"Arctic reindeer undergo a seasonal eye color change that enhances their vision in varying light conditions."},{"key":"B","text":"The tapetum lucidum is a reflective layer found in many mammal species that aids night vision."},{"key":"C","text":"Reindeer at the University of Tromsø were the first animals observed to have golden-colored eyes."},{"key":"D","text":"Arctic reindeer rely primarily on their sense of smell rather than sight to locate lichen in winter."}]$lyceon_json$::jsonb, 'A', NULL, E'The text describes how Arctic reindeer eyes change color seasonally to improve vision in different light conditions, making the option about seasonal eye color change enhancing vision the best summary. The option about the tapetum lucidum being found in many mammals misreads the passage, which calls this adaptation unique among mammals. The option about golden-colored eyes being first observed overstates what the text says — it describes the color but does not claim a first observation. The option about relying on smell contradicts the passage, which emphasizes visual adaptation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23STV4R', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an essay for a geology class and wants to present the evidence that challenges the traditional model of Earth''s inner core as a uniform solid sphere. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24NR4OR', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Architect Priya Chadha designed a community library in Jaipur using rammed-earth walls, a technique in which moist soil is compressed into dense, load-bearing structures. Critics argued that rammed earth would not withstand the region''s monsoon rainfall without costly waterproofing treatments. _______ Chadha incorporated wide overhanging eaves and angled drainage channels that redirect rainwater away from the walls, addressing the moisture concern through architectural design rather than chemical sealants.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"Instead,"},{"key":"D","text":"Likewise,"}]$lyceon_json$::jsonb, 'C', NULL, E'The critics expected that costly waterproofing treatments would be necessary, but Chadha used architectural features as an alternative solution. "Instead," correctly signals that her approach substituted one method (design elements) for the anticipated one (chemical sealants). "Furthermore," implies that the design features are additional information building on the critics'' point, but Chadha''s solution is a counterpoint to their concern, not a continuation of it. "Specifically," would introduce a more detailed version of the same idea, but Chadha''s approach contradicts rather than elaborates on the critics'' prediction. "Likewise," signals similarity between ideas, but the passage presents Chadha''s solution as an alternative to, not a parallel of, the waterproofing treatments the critics expected.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW255QAAD', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Katya Novikova documented the migration patterns of leatherback sea turtles across the South Atlantic from 2017 to 2023. Her tracking data revealed that the turtles consistently followed warm ocean currents rather than the shortest geographic routes. _______ Novikova''s findings suggest that thermal navigation, rather than simple distance minimization, is the primary driver of leatherback migratory behavior.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"On the other hand,"},{"key":"C","text":"Meanwhile,"},{"key":"D","text":"Subsequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence following the blank restates the observation about turtles following warm currents as a broader conclusion about thermal navigation. "In other words," correctly signals that the upcoming statement is a restatement or rephrasing of the preceding idea. "On the other hand," would introduce a contrasting perspective, but the final sentence reinforces rather than opposes the tracking data. "Meanwhile," implies simultaneous but separate events, which does not fit since the final sentence interprets the same data rather than describing a concurrent occurrence. "Subsequently," indicates chronological sequence, but the conclusion is an interpretation of the data, not a later event.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26TI2ZH', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes a difference in how the authors of the two texts interpret the same phenomenon?', E'Text 1: Literary scholar Anwen Griffith argues that the abrupt stylistic shifts in poet Dafydd ap Llewellyn''s later sonnets — shorter lines, fragmented syntax, irregular meter — reflect a deliberate artistic evolution. Griffith points to ap Llewellyn''s 1932 correspondence with editor Sioned Prys, in which the poet describes his desire to "shatter the vessel of form so that meaning might escape its walls."
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28PA3CD', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the Rijksmuseum commissioned a public restoration of Rembrandt''s The Night Watch in 2019, conservators discovered that earlier repair campaigns _____ a layer of varnish that had subtly but significantly altered the painting''s color balance over three centuries.', $lyceon_json$[{"key":"A","text":"has applied"},{"key":"B","text":"applying"},{"key":"C","text":"had applied"},{"key":"D","text":"have applied"}]$lyceon_json$::jsonb, 'C', NULL, E'The verb "discovered" establishes a past-tense narrative. The application of varnish during earlier repair campaigns occurred before the conservators'' discovery, so the past perfect tense is required to indicate an action completed prior to another past event. "Had applied" correctly expresses this temporal sequence. "Has applied" is incorrect because the singular present perfect does not agree with the plural subject "campaigns" and fails to establish the proper temporal relationship with the past-tense "discovered." "Applying" is a participle, not a finite verb, and cannot serve as the main verb of the clause. "Have applied" uses the present perfect, which indicates an action with present relevance, but the context situates both events in the past, requiring the past perfect to distinguish the earlier action.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2963SRB', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, how would the author of Text 2 most likely characterize the approach described in Text 1?', E'Text 1: Ecologist Rina Subramanian advocates for single-species conservation programs, arguing that directing all available funding toward the most critically endangered species in a habitat — such as the Javan rhinoceros — maximizes the probability of preventing extinction for that species.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ACGA7Y', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The conservator at the Hermitage Museum carefully removed the deteriorated canvas lining from a seventeenth-century maritime _____ applied a new adhesive backing using a technique developed specifically for oil-on-canvas works of that era.', $lyceon_json$[{"key":"A","text":"painting, and applied"},{"key":"B","text":"painting; applied"},{"key":"C","text":"painting, applied"},{"key":"D","text":"painting and applied"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence has a single subject—"The conservator"—with two verbs: "removed" and "applied." This is a compound predicate, not a compound sentence, because both verbs share one subject. In a compound predicate with two elements joined by "and," no comma is placed before the conjunction. Adding a comma before "and" would incorrectly treat the construction as two independent clauses, but "applied a new adhesive backing" lacks its own subject and is not independent. A semicolon is incorrect because what follows—"applied a new adhesive backing"—has no subject and therefore cannot stand as an independent clause. A comma without a conjunction improperly splits the compound predicate and produces a comma-splice-like error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D0OC6W', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Sociologist Elara Voss argues that remote work arrangements uniformly increase employee productivity because workers can eliminate commute time and design their own schedules, leading to more focused work hours.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D2ZYK7', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 2019, marine biologist Ayana Okafor published a study challenging the long-held assumption that deep-sea bioluminescence serves primarily as a predator deterrent. Okafor''s team observed 347 species of mesopelagic fish across seventeen expeditions in the Coral Sea and found that bioluminescent displays were most frequently directed at members of the same species during mating season. While some species did employ sudden flashes when approached by predators, Okafor argued that this defensive use was secondary to the communicative function. Her findings prompted a re-evaluation of bioluminescence research, which had for decades prioritized the predator-deterrent hypothesis almost exclusively.', $lyceon_json$[{"key":"A","text":"Okafor's research suggests that bioluminescence in deep-sea fish functions primarily as intraspecies communication rather than as a defense against predators."},{"key":"B","text":"Okafor proved that predator deterrence plays no meaningful role in the bioluminescent behavior of mesopelagic fish."},{"key":"C","text":"Deep-sea expeditions in the Coral Sea have cataloged more bioluminescent fish species than researchers previously estimated."},{"key":"D","text":"Marine biologists have recently begun studying bioluminescence in mesopelagic fish for the first time."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Okafor''s finding that bioluminescence is used primarily for same-species communication, challenging the predator-deterrent hypothesis. The option stating Okafor proved predator deterrence plays no role overstates her argument — she called it secondary, not nonexistent. The option about cataloging more species than estimated introduces a claim not present in the text. The option about studying bioluminescence for the first time contradicts the passage, which says the field had decades of prior research.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DUX6UJ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Ecologists studying the decline of monarch butterfly populations in eastern North America have hypothesized that the loss of milkweed plants along agricultural corridors is the primary driver. Milkweed is the sole host plant for monarch larvae, and widespread adoption of herbicide-resistant crops since the late 1990s has dramatically reduced milkweed density in farming regions. The researchers suggest that restoring milkweed along highway medians and field margins could reverse the population decline.', $lyceon_json$[{"key":"A","text":"Monarch populations in regions where milkweed density has remained stable show no significant decline over the same period."},{"key":"B","text":"Herbicide-resistant crop varieties have been adopted at higher rates in western North America than in eastern North America."},{"key":"C","text":"Several species of native bees have also declined in regions where herbicide-resistant crops are prevalent."},{"key":"D","text":"Monarch butterflies occasionally lay eggs on plants other than milkweed when milkweed is unavailable."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis links milkweed loss to monarch decline. The finding that monarch populations remain stable where milkweed density is unchanged directly supports this causal connection. The finding about herbicide adoption rates in western versus eastern regions does not address whether milkweed loss causes monarch decline. The finding about native bee decline is about a different species and does not specifically support the milkweed-monarch link. The finding about monarchs occasionally using other plants actually weakens the hypothesis by suggesting milkweed loss might be partially offset.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EKZZ96', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Cognitive scientist Elara Mäkinen has proposed that the human tendency to anthropomorphize — to attribute human emotions, intentions, and mental states to nonhuman entities — is not a cognitive error but an adaptive heuristic that evolved because the costs of its errors are asymmetric. Falsely attributing agency to a rustling bush (assuming a predator when there is none) carries a low cost: momentary vigilance. Failing to attribute agency when a predator is actually present, however, carries a potentially fatal cost. Mäkinen extends this framework beyond predator detection, arguing that because the heuristic is domain-general rather than domain-specific, ________', $lyceon_json$[{"key":"A","text":"humans apply it broadly, anthropomorphizing not only animals but also weather patterns, machines, and abstract forces, even when no survival advantage exists."},{"key":"B","text":"humans have gradually learned to suppress the heuristic in modern environments where predator threats are minimal."},{"key":"C","text":"the heuristic operates only in situations that closely resemble ancestral predator encounters, such as hearing unexpected sounds in darkness."},{"key":"D","text":"anthropomorphism is more prevalent in cultures that maintain close contact with wild animals than in urbanized societies."}]$lyceon_json$::jsonb, 'A', NULL, E'Mäkinen''s argument distinguishes domain-general from domain-specific heuristics. The passage states the heuristic is domain-general, so the logical completion is that it applies broadly beyond its original survival context — to machines, weather, and abstract forces. The option about humans learning to suppress the heuristic contradicts the passage''s logic; if the asymmetric cost structure favors over-attribution, suppression would be selected against. The option limiting the heuristic to predator-like encounters directly contradicts Mäkinen''s claim that it is domain-general, not domain-specific. The option about cultural variation introduces an empirical claim about cultural differences unsupported by the passage''s theoretical framework.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F18KYB', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing an article about the guanaco for readers unfamiliar with South American wildlife. The student wants to introduce the guanaco by describing its basic characteristics and habitat. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FC9AA9', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historian Kenji Watanabe has documented how the introduction of mechanical clocks in fourteenth-century European monasteries gradually transformed labor practices beyond the monastery walls. Before mechanical timekeeping, agricultural and artisanal work had been organized around natural rhythms — daylight, seasons, and the variable canonical hours marked by church bells. Mechanical clocks, however, divided the day into uniform segments independent of season or sunlight. Watanabe argues that once merchants and guild masters in nearby towns adopted clock-regulated schedules, ________', $lyceon_json$[{"key":"A","text":"the concept of a standardized workday became possible, fundamentally altering the relationship between labor and time."},{"key":"B","text":"monasteries lost their cultural influence because secular institutions no longer relied on church bells for timekeeping."},{"key":"C","text":"agricultural workers immediately abandoned seasonal rhythms in favor of clock-based scheduling."},{"key":"D","text":"mechanical clocks became less accurate than the canonical hours they replaced, leading to widespread disputes over working hours."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces a shift from natural, variable time-reckoning to uniform, clock-based time. The logical completion is that clock-regulated schedules enabled the standardized workday, transforming the labor-time relationship. The option about monasteries losing cultural influence overstates the implications — the passage discusses timekeeping practices, not overall cultural influence. The option about immediate abandonment of seasonal rhythms is too extreme; the passage describes a gradual transformation, not an immediate one. The option about mechanical clocks being less accurate contradicts the passage''s framing, which presents clocks as providing uniform, reliable segments rather than as inferior to canonical hours.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G3BYTJ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The municipal government of Tbilisi allocated seventeen million lari to restore the sulfur bathhouses in the Abanotubani _____ which have attracted visitors to the Georgian capital since the thirteenth century.', $lyceon_json$[{"key":"A","text":"district; which"},{"key":"B","text":"district, which"},{"key":"C","text":"district. Which"},{"key":"D","text":"district which"}]$lyceon_json$::jsonb, 'B', NULL, E'The clause "which have attracted visitors to the Georgian capital since the thirteenth century" is a nonrestrictive relative clause providing additional information about the Abanotubani district, which has already been specifically identified. Because it is nonrestrictive, it must be set off by a comma. A semicolon is incorrect because a dependent clause beginning with "which" is not an independent clause. A period followed by "Which" creates a sentence fragment, since a relative clause cannot stand alone. Omitting all punctuation would incorrectly treat the clause as restrictive, but the district is already uniquely identified, making the clause nonrestrictive and requiring a comma.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GD5RIA', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The pottery fragments recently unearthed along the banks of the Irrawaddy River in central _____ evidence that sophisticated ceramic glazing techniques existed in the region far earlier than scholars had believed.', $lyceon_json$[{"key":"A","text":"Myanmar provides"},{"key":"B","text":"Myanmar provide"},{"key":"C","text":"Myanmar has provided"},{"key":"D","text":"Myanmar is providing"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "fragments," a plural noun. The intervening prepositional phrases—"recently unearthed along the banks of the Irrawaddy River in central Myanmar"—do not change the number of the subject. The verb must agree with "fragments" and therefore must be plural. "Provide" is the correct plural present-tense form. "Provides" is singular and does not agree with the plural subject. "Has provided" uses the singular auxiliary "has," which fails to agree with the plural subject. "Is providing" uses the singular auxiliary "is," which likewise does not agree.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 55, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JO7AAA', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the sudden decline in monarch butterfly populations across the Great Plains nor the concurrent disappearance of native milkweed from agricultural _____ entirely attributable to a single environmental factor, according to a comprehensive study published by entomologists at the University of Kansas.', $lyceon_json$[{"key":"A","text":"corridors are"},{"key":"B","text":"corridors is"},{"key":"C","text":"corridors have been"},{"key":"D","text":"corridors were"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence uses the correlative conjunction "neither...nor" to connect two singular subjects: "the sudden decline" and "the concurrent disappearance." When "neither...nor" connects two singular subjects, the verb must be singular. "Is" correctly agrees with these singular subjects. The proximity of the plural noun "corridors"—part of the prepositional phrase "from agricultural corridors"—may create the impression that a plural verb is needed, but "corridors" is the object of the preposition, not the subject. "Are" is plural and does not agree with the singular subjects. "Have been" is likewise plural and fails to agree. "Were" is both plural and past tense; the study describes an ongoing condition, and the past tense is inconsistent with the present-tense framing of the finding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K2T41S', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'In her 2019 monograph on urban soil contamination, geochemist Priya Dasgupta argues that municipal composting programs do not merely reduce landfill volume but actively ______ degraded soils, restoring microbial diversity and nutrient cycling capacity to plots that decades of industrial use had rendered biologically inert.', $lyceon_json$[{"key":"A","text":"rejuvenate"},{"key":"B","text":"excavate"},{"key":"C","text":"partition"},{"key":"D","text":"inventory"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that composting programs restore microbial diversity and nutrient cycling to biologically inert soils. "Rejuvenate" means to restore vitality, which directly aligns with this description of bringing degraded soils back to biological activity. "Excavate" means to dig up or remove soil, which describes a physical action unrelated to restoring biological health. "Partition" means to divide into sections, which is incoherent in the context of restoring soil quality. "Inventory" means to catalog or count items, which makes no sense when applied to the act of restoring degraded soils.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K6G6WD', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Urban ecologist Priya Chandrasekaran studied pigeon populations in eleven mid-sized European cities and found that pigeons nesting on buildings constructed before 1920 had significantly higher reproductive success than those nesting on modern glass-and-steel structures. Chandrasekaran attributed the difference to the abundance of ledges, cornices, and recessed ornamental features on older buildings, which provide sheltered nesting sites. By contrast, the smooth facades of contemporary architecture offer few such features. Chandrasekaran''s findings suggest that as cities demolish older buildings and replace them with modern ones, ________', $lyceon_json$[{"key":"A","text":"urban pigeon populations in those cities are likely to decline due to reduced availability of suitable nesting sites."},{"key":"B","text":"architects will begin incorporating ornamental features into new buildings specifically to support pigeon populations."},{"key":"C","text":"pigeons will migrate from European cities to rural areas where older stone structures remain common."},{"key":"D","text":"the reproductive success of pigeons nesting on modern buildings will gradually increase as the birds adapt."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that older buildings provide better nesting sites and that pigeons on older buildings have higher reproductive success. The logical completion is that replacing older buildings with modern ones would reduce suitable nesting sites and thus likely reduce pigeon populations. The option about architects incorporating ornamental features goes far beyond what the research suggests — nothing in the passage indicates architectural response to pigeon needs. The option about migration to rural areas introduces an unsupported behavioral claim. The option about gradual adaptation assumes evolutionary or behavioral change not supported by the passage''s evidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L3OB7L', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a report on Venetian glassmaking and wants to emphasize the contrast between the historical secrecy of Murano glassmakers and the modern openness of the craft. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L7O6PO', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Marine biologists studying the Mariana Trench have found that certain organisms flourish at depths once considered inhospitable. Rather than being harmed by extreme pressure, these creatures have ______ physiological mechanisms that allow them to thrive where most life cannot survive.', $lyceon_json$[{"key":"A","text":"developed"},{"key":"B","text":"abandoned"},{"key":"C","text":"concealed"},{"key":"D","text":"postponed"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes organisms that flourish under extreme conditions by having physiological mechanisms that help them thrive. "Developed" logically completes the sentence because it means the organisms evolved or acquired these mechanisms. "Abandoned" implies giving up mechanisms, which contradicts the passage''s claim that they thrive. "Concealed" means hidden, which makes no sense in the context of physiological adaptation. "Postponed" means delayed, which is incoherent when applied to physiological mechanisms enabling survival.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q6ETTT', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In the mountainous regions of western Guatemala, artisans have practiced backstrap loom weaving for over two thousand years. Passed down through generations of Indigenous _____ the technique requires the weaver to maintain constant tension on the threads by leaning back against a strap secured around the lower back.', $lyceon_json$[{"key":"A","text":"women, the"},{"key":"B","text":"women; the"},{"key":"C","text":"women the"},{"key":"D","text":"women: the"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase "Passed down through generations of Indigenous women" is an introductory participial phrase modifying "the technique." A comma is required to separate this introductory modifier from the main clause. A semicolon would be incorrect because the participial phrase is not an independent clause and cannot stand alone as a sentence. Omitting punctuation entirely creates an unclear run-together that obscures the boundary between modifier and main clause. A colon is incorrect because the element before it must be an independent clause, and a participial phrase does not qualify.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R4AU83', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The city council''s revised zoning proposal mandates that the contractor _____ all demolition debris from the Riverside Terrace site within forty-five days and submit a certified environmental impact report before any new construction commences.', $lyceon_json$[{"key":"A","text":"removes"},{"key":"B","text":"will remove"},{"key":"C","text":"remove"},{"key":"D","text":"removed"}]$lyceon_json$::jsonb, 'C', NULL, E'The verb "mandates" introduces a mandative subjunctive construction. In Standard English, verbs expressing demand, recommendation, or requirement are followed by a "that" clause in which the verb takes the bare (base) form, regardless of the subject''s person or number. "Remove" is the correct base form, and the parallel verb "submit" later in the sentence confirms this construction. "Removes" is the indicative third-person singular, which is incorrect in a mandative subjunctive clause. "Will remove" incorrectly introduces a modal auxiliary into a subjunctive construction. "Removed" places the action in the past tense, contradicting the forward-looking mandate expressed by the sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SSIVND', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'Philosopher Renata Salecl has argued that the modern proliferation of consumer choices — far from empowering individuals — actually intensifies anxiety and self-blame. When faced with forty-seven varieties of breakfast cereal or hundreds of retirement fund options, people do not simply select and move on. Instead, they agonize over whether their selection was optimal, a phenomenon psychologists call "maximizing." Salecl contends that this maximizing tendency is not an innate personality trait but rather a predictable response to market structures that frame every decision as an expression of one''s identity. In her view, the rhetoric of "personal choice" obscures the systemic forces — advertising, deregulation, the erosion of collective provisions — that created the overwhelming array of options in the first place. By treating dissatisfaction as a failure of individual decision-making, societies avoid confronting the structural conditions that manufactured the problem.', $lyceon_json$[{"key":"A","text":"The abundance of consumer choices generates anxiety because market structures encourage people to treat every decision as identity-defining, masking the systemic origins of that abundance."},{"key":"B","text":"Maximizing is an innate psychological tendency that worsens when consumers are presented with large numbers of similar products."},{"key":"C","text":"Consumer dissatisfaction stems primarily from advertising campaigns that exaggerate the differences between nearly identical products."},{"key":"D","text":"Reducing the number of available consumer options would eliminate the anxiety associated with decision-making in modern markets."}]$lyceon_json$::jsonb, 'A', NULL, E'Salecl''s central claim, as presented in the passage, is that market structures frame choices as identity expressions, generating anxiety, while the rhetoric of personal choice obscures systemic causes — captured by the option about market structures and systemic origins. The option calling maximizing an innate trait directly contradicts the passage, which says Salecl considers it a predictable response to market structures, not innate. The option focusing solely on advertising captures only one of several systemic forces mentioned, missing the broader argument. The option about reducing options proposing a solution goes beyond what the passage argues — Salecl critiques the framing of dissatisfaction but does not prescribe that remedy.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TC3009', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall purpose of the text?', E'Acoustician Jenna Merfeld has demonstrated that the resonant frequency of a violin''s air cavity — the so-called Helmholtz resonance — is determined primarily by the size of the f-holes, not by the volume of the body as instrument makers have traditionally assumed. Merfeld''s laser-vibrometry measurements of 47 violins spanning four centuries show that f-hole area alone accounts for 89% of the variance in Helmholtz resonance, whereas body volume accounts for less than 7%. She acknowledges, however, that her sample underrepresents instruments by provincial makers whose workshops lay outside the major Italian schools, and that including such instruments might alter the relative contributions of these two variables.', $lyceon_json$[{"key":"A","text":"To present a researcher's findings that challenge a traditional assumption, while noting a limitation that qualifies those findings."},{"key":"B","text":"To argue that provincial violin makers were more skilled than those from the major Italian schools."},{"key":"C","text":"To explain the complete physical mechanism by which f-hole size determines sound quality in stringed instruments."},{"key":"D","text":"To compare laser vibrometry with older measurement methods and advocate for its broader adoption."}]$lyceon_json$::jsonb, 'A', NULL, E'The text presents Merfeld''s finding that f-hole area, not body volume, primarily determines Helmholtz resonance — directly challenging the traditional assumption. It then notes that her sample underrepresents provincial makers, qualifying her conclusion. This matches presenting findings that challenge an assumption while noting a limitation. The text never claims provincial makers were more skilled; it only notes they are underrepresented in the sample. The passage discusses one specific acoustic property (Helmholtz resonance), not a complete mechanism of sound quality. And while laser vibrometry is mentioned as a tool, the text does not compare it to other methods or advocate for its adoption.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WJN217', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most effectively support the claim presented in the text?', E'Literary scholar Tomás Vergara has argued that the novels of Chilean author María Luisa Bombal are best understood not as surrealist experiments but as precise psychological portraits rendered through poetic compression. According to Vergara, Bombal''s dreamlike imagery — fog-shrouded gardens, disembodied voices, characters who seem to dissolve into landscape — is not decorative ambiguity but rather a controlled technique for externalizing her protagonists'' interior states of isolation and longing.', $lyceon_json$[{"key":"A","text":"\"Bombal's recurring image of the protagonist submerging into a forest pool in 'The Final Mist' directly mirrors the character's withdrawal from a marriage she experiences as suffocating, making the surreal scene an externalization of psychological reality.\""},{"key":"B","text":"\"Bombal drew extensively on European surrealist manifestos, particularly Breton's 'Nadja,' which she read during her years in Paris and which shaped her commitment to automatic writing.\""},{"key":"C","text":"\"The dreamlike quality of Bombal's prose has led many readers to classify her alongside magical realists such as García Márquez and Allende, a grouping that highlights shared Latin American literary traditions.\""},{"key":"D","text":"\"Bombal's shortest novel can be read in a single sitting, which contributes to its emotional intensity but also limits its capacity for the kind of sustained character development found in longer works.\""}]$lyceon_json$::jsonb, 'A', NULL, E'Vergara''s claim is that Bombal''s dreamlike imagery externalizes her protagonists'' psychological states. The quotation connecting the forest pool image to the character''s psychological withdrawal directly supports this by providing a concrete example of imagery functioning as externalized psychology. The quotation about European surrealist manifestos and automatic writing would actually undermine Vergara''s claim by linking Bombal to surrealism rather than psychological portraiture. The quotation about classification alongside magical realists discusses genre grouping, not the psychological function of imagery. The quotation about novel length addresses emotional intensity and character development, which is tangential to whether dreamlike imagery serves a psychological purpose.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X9K42K', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The larvae of the painted lady butterfly (Vanessa cardui) feed on over 300 plant species, an unusually broad diet for a lepidopteran. [underlined] Most butterfly species, by contrast, are specialists whose larvae depend on a single genus or even a single species of host plant. [/underlined] This dietary flexibility allows painted ladies to breed across an enormous geographic range, from sub-Saharan Africa to northern Scandinavia.', $lyceon_json$[{"key":"A","text":"It provides a contrast that highlights an unusual characteristic of the painted lady butterfly."},{"key":"B","text":"It presents a finding that challenges a claim made earlier in the text."},{"key":"C","text":"It offers a possible explanation for the geographic range of most butterfly species."},{"key":"D","text":"It introduces a new topic unrelated to the painted lady butterfly."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence describes how most butterfly species are specialists, which directly contrasts with the painted lady''s unusually broad diet mentioned in the preceding sentence. This contrast highlights how exceptional the painted lady''s dietary flexibility is. The sentence does not challenge any earlier claim — it reinforces the point that the painted lady is unusual. It does not explain the geographic range of most butterflies; the passage discusses only the painted lady''s range. And the sentence is clearly related to the painted lady, not a new unrelated topic.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y80C1E', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The fruit fly Drosophila melanogaster has been a staple of genetics laboratories since the early twentieth century. Researchers initially favored it because of its short reproductive cycle and easily observable traits. _______ the species remains one of the most widely used model organisms in biological research today.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes favorable qualities of the fruit fly and then states it continues to be widely used, which is a logical consequence of those qualities. "Accordingly," signals a result that follows from the preceding information. "Nevertheless," incorrectly implies a contrast or concession where none exists, since continued use is consistent with the advantages described. "In contrast," wrongly signals opposition between ideas that are aligned. "For instance," would introduce a specific example, but the final sentence is a general statement about the species'' ongoing prominence, not an illustrative case.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YEKGAJ', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1953, biochemist Erwin Chargaff published data showing that in any sample of DNA, the amount of adenine nearly equals the amount of thymine, and the amount of guanine nearly equals the amount of cytosine. These ratios held regardless of the organism from which the DNA was extracted — yeast, sea urchin, or calf thymus tissue. Chargaff himself did not propose a structural model to account for these regularities, but his findings imposed a powerful constraint on anyone who did: any viable model of DNA''s architecture had to explain why these base-pair ratios are universal.', $lyceon_json$[{"key":"A","text":"It describes an experimental finding, notes its consistency across organisms, and then explains its significance for subsequent research."},{"key":"B","text":"It proposes a structural model for DNA, tests the model against data from multiple organisms, and concludes that the model is correct."},{"key":"C","text":"It presents two competing hypotheses about DNA composition and argues that one is better supported than the other."},{"key":"D","text":"It traces the career of a single scientist from an early discovery through a series of increasingly important contributions."}]$lyceon_json$::jsonb, 'A', NULL, E'The text first presents Chargaff''s data on base-pair ratios, then notes these ratios held across diverse organisms, and finally explains that the findings constrained future structural models. This matches the description of presenting a finding, noting its consistency, and explaining its significance. The text explicitly states Chargaff did not propose a structural model, so the option claiming the text proposes and tests a model is factually wrong. The passage presents only one set of findings, not two competing hypotheses. And the text focuses on a single discovery and its implications rather than tracing a career through multiple contributions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z35868', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Dr. Fariha Qadir''s research on neural oscillations challenges a widely held assumption in cognitive _____ that gamma-wave activity during sleep serves primarily a restorative function. Her findings instead suggest that these oscillations actively reorganize synaptic connections, strengthening pathways associated with recently acquired motor skills.', $lyceon_json$[{"key":"A","text":"neuroscience, that"},{"key":"B","text":"neuroscience: that"},{"key":"C","text":"neuroscience that"},{"key":"D","text":"neuroscience; that"}]$lyceon_json$::jsonb, 'C', NULL, E'The clause "that gamma-wave activity during sleep serves primarily a restorative function" is a noun complement clause defining the content of the "assumption." No punctuation should separate a noun from its essential complement clause. Inserting a comma incorrectly treats the complement as a nonrestrictive element when it is essential to the sentence''s meaning. A colon is incorrect because the text preceding it—"challenges a widely held assumption in cognitive neuroscience"—is not a complete independent clause without the complement that specifies what the assumption is. A semicolon is likewise incorrect because the "that" clause is a dependent complement clause, not an independent clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
